package com.exelynt.booking.controller; import com.exelynt.booking.dto.*; import com.exelynt.booking.service.AuthService; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; @RestController @RequestMapping("/auth") public class AuthController {private final AuthService service;public AuthController(AuthService s){service=s;}@PostMapping("/login") public LoginResponse login(@Valid @RequestBody LoginRequest request){return service.login(request);}}
